#### **`script.js`**
```javascript
// Key for localStorage
const LOG_KEY = 'userInputLog';

// DOM Elements
const logForm = document.getElementById('logForm');
const userInput = document.getElementById('userInput');
const logList = document.getElementById('logList');
const clearBtn = document.getElementById('clearBtn');

// Load logs from localStorage
function loadLogs() {
  const logs = getLogs();
  logList.innerHTML = '';
  logs.forEach((entry, index) => {
    const li = document.createElement('li');
    li.textContent = `${new Date(entry.timestamp).toLocaleString()}: ${entry.value}`;

    // Add delete button for each entry
    const deleteBtn = document.createElement('button');
    deleteBtn.textContent = '❌';
    deleteBtn.style.float = 'right';
    deleteBtn.style.marginLeft = '10px';
    deleteBtn.onclick = () => deleteEntry(index);

    li.appendChild(deleteBtn);
    logList.appendChild(li);
  });
}

// Get logs from localStorage
function getLogs() {
  const logs = localStorage.getItem(LOG_KEY);
  return logs ? JSON.parse(logs) : [];
}

// Save a new log entry
function saveLog(value) {
  const logs = getLogs();
  logs.push({
    value: value,
    timestamp: new Date().toISOString()
  });
  localStorage.setItem(LOG_KEY, JSON.stringify(logs));
}

// Delete an entry by index
function deleteEntry(index) {
  const logs = getLogs();
  logs.splice(index, 1);
  localStorage.setItem(LOG_KEY, JSON.stringify(logs));
  loadLogs();
}

// Clear all logs
function clearLogs() {
  if (confirm("Are you sure you want to delete all logs?")) {
    localStorage.removeItem(LOG_KEY);
    loadLogs();
  }
}

// Event Listeners
logForm.addEventListener('submit', (e) => {
  e.preventDefault();
  const value = userInput.value.trim();
  if (value) {
    saveLog(value);
    userInput.value = '';
    loadLogs();
  }
});

clearBtn.addEventListener('click', clearLogs);

// Initial load
loadLogs();
```

---

### ✅ Features:
- Logs user text input with timestamp.
- Stores data in `localStorage` (plaintext JSON string).
- Displays logs in reverse chronological order.
- Allows deletion of individual entries or clearing all.
- No server or database required — fully client-side.

### 📝 Notes:
- Data is stored **locally in the browser** and persists across page reloads.
- Data is **not shared across devices** or users.
- For enhanced security, avoid logging sensitive data in plaintext.

