Here is a simple JavaScript script that provides encryption functionality using the Web Crypto API. This example demonstrates how to encrypt text data using AES-GCM (Advanced Encryption Standard - Galois/Counter Mode), which is a secure and widely used encryption method in modern browsers.

```javascript
/**
 * Simple Encryption Script using Web Crypto API
 * Supports encryption of text data with a password-derived key.
 */

// Function to encode a string to Uint8Array
function encodeText(text) {
    const encoder = new TextEncoder();
    return encoder.encode(text);
}

// Function to decode Uint8Array to string
function decodeText(data) {
    const decoder = new TextDecoder();
    return decoder.decode(data);
}

// Function to derive an encryption key from a password using PBKDF2
async function deriveKey(password, salt) {
    const enc = new TextEncoder();
    const keyMaterial = await crypto.subtle.importKey(
        'raw',
        enc.encode(password),
        { name: 'PBKDF2' },
        false,
        ['deriveKey']
    );

    return await crypto.subtle.deriveKey(
        {
            name: 'PBKDF2',
            salt: salt,
            iterations: 100000,
            hash: 'SHA-256'
        },
        keyMaterial,
        { name: 'AES-GCM', length: 256 },
        false,
        ['encrypt', 'decrypt']
    );
}

// Function to encrypt text with a password
async function encryptText(plaintext, password) {
    // Generate a random salt and IV (Initialization Vector)
    const salt = crypto.getRandomValues(new Uint8Array(16));
    const iv = crypto.getRandomValues(new Uint8Array(12)); // AES-GCM requires 12-byte IV

    // Derive key from password
    const key = await deriveKey(password, salt);

    // Encrypt the plaintext
    const encodedPlaintext = encodeText(plaintext);
    const encryptedData = await crypto.subtle.encrypt(
        {
            name: 'AES-GCM',
            iv: iv
        },
        key,
        encodedPlaintext
    );

    // Return salt, iv, and encrypted data as a single object (must be converted to base64 or similar for storage/transmission)
    const encryptedArray = new Uint8Array(encryptedData);
    return {
        salt: btoa(String.fromCharCode(...salt)),
        iv: btoa(String.fromCharCode(...iv)),
        data: btoa(String.fromCharCode(...encryptedArray))
    };
}

// Function to decrypt text with a password
async function decryptText(encryptedObject, password) {
    const salt = Uint8Array.from(atob(encryptedObject.salt), c => c.charCodeAt(0));
    const iv = Uint8Array.from(atob(encryptedObject.iv), c => c.charCodeAt(0));
    const data = Uint8Array.from(atob(encryptedObject.data), c => c.charCodeAt(0));

    // Derive key from password (same as encryption)
    const key = await deriveKey(password, salt);

    // Decrypt the data
    const decrypted = await crypto.subtle.decrypt(
        {
            name: 'AES-GCM',
            iv: iv
        },
        key,
        data
    );

    // Return the decrypted plaintext
    return decodeText(decrypted);
}

// Example usage:
(async () => {
    const plaintext = "This is a secret message!";
    const password = "my-strong-password";

    try {
        // Encrypt
        const encrypted = await encryptText(plaintext, password);
        console.log("Encrypted:", encrypted);

        // Decrypt
        const decrypted = await decryptText(encrypted, password);
        console.log("Decrypted:", decrypted);
    } catch (error) {
        console.error("Error during encryption/decryption:", error);
    }
})();
```

### Features:
- **Secure Key Derivation**: Uses PBKDF2 with 100,000 iterations and SHA-256 to derive a strong key from a password.
- **AES-GCM Encryption**: Provides confidentiality and integrity.
- **Random Salt and IV**: Ensures that the same plaintext and password produce different ciphertexts each time.
- **Browser Compatibility**: Uses the standard Web Crypto API available in modern browsers.

### Usage Notes:
- The encrypted output includes `salt`, `iv`, and `data`, all Base64-encoded for easy storage or transmission.
- To store encrypted data, save the entire object (e.g., as JSON).
- Always use a strong password for meaningful security.
- This script runs entirely in the browser and does not send data over the network.

