/**
 * Discount Code Generator for E-Commerce
 * Automatically creates and displays discount codes for eligible user groups.
 */

class DiscountCodeGenerator {
    constructor() {
        this.generatedCodes = new Set(); // Prevent duplicate codes
        this.codePrefix = "DISC";
        this.codeLength = 8;
    }

    /**
     * Generates a unique discount code.
     * @returns {string} A unique discount code.
     */
    generateCode() {
        const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
        let code;
        do {
            code = this.codePrefix;
            for (let i = 0; i < this.codeLength - this.codePrefix.length; i++) {
                code += chars.charAt(Math.floor(Math.random() * chars.length));
            }
        } while (this.generatedCodes.has(code));

        this.generatedCodes.add(code);
        return code;
    }

    /**
     * Determines if the user is eligible for a discount.
     * @param {string} userType - Type of user: 'new', 'returning', 'premium', etc.
     * @returns {boolean} True if eligible.
     */
    isEligibleUser(userType) {
        const eligibleGroups = ['new', 'premium', 'vip'];
        return eligibleGroups.includes(userType.toLowerCase());
    }

    /**
     * Displays the discount code on the page.
     * @param {string} code - The discount code to display.
     */
    showDiscount(code) {
        const discountElement = document.getElementById('discount-offer') ||
                                document.createElement('div');
        discountElement.id = 'discount-offer';
        discountElement.style.padding = '15px';
        discountElement.style.backgroundColor = '#eaffea';
        discountElement.style.border = '1px solid #4CAF50';
        discountElement.style.borderRadius = '5px';
        discountElement.style.fontWeight = 'bold';
        discountElement.style.textAlign = 'center';
        discountElement.innerHTML = `
            🎉 Special Offer! Use code <span style="color: #d32f2f;">${code}</span> 
            for a discount on your order!
        `;

        // Insert at top of body or a specific container
        const container = document.body; // or use a specific element like .header
        container.insertBefore(discountElement, container.firstChild);
    }

    /**
     * Main method to apply discount logic.
     * @param {string} userType - The type of user (e.g., 'new', 'premium').
     */
    applyDiscount(userType) {
        if (this.isEligibleUser(userType)) {
            const code = this.generateCode();
            this.showDiscount(code);
            console.log(`Discount code ${code} shown to ${userType} user.`);
            return code;
        } else {
            console.log(`User type '${userType}' is not eligible for a discount.`);
            return null;
        }
    }
}

