To achieve your goal of displaying randomly chosen quotes from an external database via JavaScript, you can use the `fetch` API to make a secure GET request to the database's endpoint. Since the database requires an API key for authentication, you'll need to include it in the request headers.

Below is a clean and secure JavaScript snippet that you can embed in your website (e.g., inside a `<script>` tag or in an external `.js` file):

```javascript
// Function to fetch and display a random quote
async function fetchRandomQuote() {
    const apiUrl = 'https://api.example.com/quotes/random'; // Replace with your actual API endpoint
    const apiKey = 'sgq-wi17gabn1sl';

    try {
        const response = await fetch(apiUrl, {
            method: 'GET',
            headers: {
                'Authorization': `Bearer ${apiKey}`,
                'Content-Type': 'application/json'
            }
        });

        if (!response.ok) {
            throw new Error(`Failed to fetch quote: ${response.status} ${response.statusText}`);
        }

        const data = await response.json();

        // Assuming the API returns a JSON object like: { "quote": "Life is what happens...", "author": "John Lennon" }
        const quoteText = data.quote;
        const quoteAuthor = data.author;

        // Update HTML elements with the fetched quote
        document.getElementById('quote-text').textContent = `"${quoteText}"`;
        document.getElementById('quote-author').textContent = `— ${quoteAuthor}`;
    } catch (error) {
        console.error('Error fetching quote:', error);
        document.getElementById('quote-text').textContent = "Failed to load quote.";
        document.getElementById('quote-author').textContent = "";
    }
}

// Call the function when the page loads
window.onload = fetchRandomQuote;
```

